using System.Collections.Generic;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "CompanionsTierList", menuName = "Data/Battle/Companions/CompanionsTier List")]
public class CompanionsTierList : ScriptableObject
{
	[Header("Tier")]
	[SerializeField]
	private CompanionTier companionTier;

	[Header("Basic Dices")]
	[SerializeField]
	private List<CompanionData> companions = new List<CompanionData>();

	public CompanionTier CompanionTier => companionTier;

	public List<CompanionData> Companions => companions;

	public CompanionData GetCompanionData(string companionName, bool logError = true)
	{
		string text = companionName.ToLower();
		for (int i = 0; i < companions.Count; i++)
		{
			if (text == companions[i].name.ToLower())
			{
				return companions[i];
			}
		}
		return null;
	}
}
